template <typename UnionPtrType>
ActionEntryPtr ActionEntry::Clone() const {
  switch (tag_) {
    case Tag::kSubheading:
      return NewSubheading(
          mojo::Clone(data_.subheading));
    case Tag::kDetails:
      return NewDetails(
          mojo::Clone(data_.details));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, ActionEntry>::value>::type*>
bool ActionEntry::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kSubheading:
      return mojo::Equals(data_.subheading, other.data_.subheading);
    case Tag::kDetails:
      return mojo::Equals(data_.details, other.data_.details);
  }

  return false;
}
