template <typename T, ConversationState::EnableIfSame<T>*>
bool operator<(const T& lhs, const T& rhs) {
  if (lhs.conversation_uuid < rhs.conversation_uuid)
    return true;
  if (rhs.conversation_uuid < lhs.conversation_uuid)
    return false;
  if (lhs.is_request_in_progress < rhs.is_request_in_progress)
    return true;
  if (rhs.is_request_in_progress < lhs.is_request_in_progress)
    return false;
  if (lhs.all_models < rhs.all_models)
    return true;
  if (rhs.all_models < lhs.all_models)
    return false;
  if (lhs.current_model_key < rhs.current_model_key)
    return true;
  if (rhs.current_model_key < lhs.current_model_key)
    return false;
  if (lhs.default_model_key < rhs.default_model_key)
    return true;
  if (rhs.default_model_key < lhs.default_model_key)
    return false;
  if (lhs.associated_content < rhs.associated_content)
    return true;
  if (rhs.associated_content < lhs.associated_content)
    return false;
  if (lhs.error < rhs.error)
    return true;
  if (rhs.error < lhs.error)
    return false;
  if (lhs.error_details < rhs.error_details)
    return true;
  if (rhs.error_details < lhs.error_details)
    return false;
  if (lhs.temporary < rhs.temporary)
    return true;
  if (rhs.temporary < lhs.temporary)
    return false;
  if (lhs.tool_use_task_state < rhs.tool_use_task_state)
    return true;
  if (rhs.tool_use_task_state < lhs.tool_use_task_state)
    return false;
  if (lhs.capabilities_enabled < rhs.capabilities_enabled)
    return true;
  if (rhs.capabilities_enabled < lhs.capabilities_enabled)
    return false;
  if (lhs.vision_model_switch_key < rhs.vision_model_switch_key)
    return true;
  if (rhs.vision_model_switch_key < lhs.vision_model_switch_key)
    return false;
  if (lhs.is_content_agent_chosen < rhs.is_content_agent_chosen)
    return true;
  if (rhs.is_content_agent_chosen < lhs.is_content_agent_chosen)
    return false;
  return false;
}


